// ── /polaris/budget: NUR Verarbeitung, KEINE eigenen HTTP-Requests ──
// Der RTDB-Knoten appStore/app-data_json wird vom vorgelagerten HTTP-Request-
// Node "RTDB app-data" geholt. Er enthält einen Wrapper { data: "<JSON-String
// des gesamten App-Payloads>", updatedAt, savedAt, savedBy } — das Feld `data`
// muss geparst werden. Reiner Lesepfad; wirft NIE (defensiv → {ok:false,error}).
try {
  const wrap = $json;
  if (!wrap || typeof wrap !== 'object' || wrap.data == null || wrap.error) {
    return [{ json: { ok: false, error: 'appStore/app-data_json nicht gefunden' } }];
  }
  let payload;
  try {
    payload = (typeof wrap.data === 'string') ? JSON.parse(wrap.data) : wrap.data;
  } catch (e) {
    return [{ json: { ok: false, error: 'data-Feld nicht parsebar' } }];
  }
  if (!payload || typeof payload !== 'object') {
    return [{ json: { ok: false, error: 'Payload leer oder ungueltig' } }];
  }
  const ent = (payload.entities && typeof payload.entities === 'object') ? payload.entities : {};
  // Entity-Maps { id -> objekt } defensiv in Arrays wandeln
  const arr = function (m) {
    if (!m || typeof m !== 'object') return [];
    return Object.keys(m).map(function (k) { return m[k]; }).filter(function (x) { return x && typeof x === 'object'; });
  };
  const budget = {
    transactions: arr(ent.transactions),
    accounts: arr(ent.accounts),
    creditCards: arr(ent.creditCards),
    subscriptions: arr(ent.subscriptions),
    financialGoals: arr(ent.financialGoals),
    purchaseProposals: arr(ent.purchaseProposals)
  };
  // kompakte Kennzahlen (bequem fuer die Sprachausgabe; roh bleibt erhalten)
  const real = budget.transactions.filter(function (t) { return t && !t.isFuture; });
  const sum = function (list) { return list.reduce(function (s, t) { return s + (Number(t.amount) || 0); }, 0); };
  const income = sum(real.filter(function (t) { return t.type === 'income'; }));
  const expense = sum(real.filter(function (t) { return t.type === 'expense'; }));
  const totalBalance = budget.accounts.reduce(function (s, a) { return s + (Number(a.balance) || 0); }, 0);
  budget.summary = {
    currency: (budget.accounts[0] && budget.accounts[0].currency) || 'CHF',
    totalBalance: totalBalance,
    income: income,
    expense: expense,
    net: income - expense,
    counts: {
      transactions: budget.transactions.length,
      accounts: budget.accounts.length,
      creditCards: budget.creditCards.length,
      subscriptions: budget.subscriptions.length,
      financialGoals: budget.financialGoals.length,
      purchaseProposals: budget.purchaseProposals.length
    }
  };
  return [{ json: { ok: true, budget: budget } }];
} catch (e) {
  return [{ json: { ok: false, error: 'Budget konnte nicht gelesen werden' } }];
}
